    PRODUCT_KEY INT,
    PRIMARY KEY (PRODUCT_KEY)
);
CREATE TABLE CUSTOMER (
    CUSTOMER_ID INT,
    PRODUCT_KEY INT,
    PRIMARY KEY (CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_KEY) REFERENCES PRODUCT(PRODUCT_KEY)
);

CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR(255),
    FOLLOWER VARCHAR(255),
    PRIMARY KEY (FOLLOWEE, FOLLOWER),
    CHECK (FOLLOWEE <> FOLLOWER)
);

CREATE TABLE EMPLOYEE (
    EMPLOYEE_ID INT,
    NAME VARCHAR(255),
    EXPERIENCE_YEARS INT,
    PRIMARY KEY (EMPLOYEE_ID),
    CHECK (EXPERIENCE_YEARS >= 0)
);
CREATE TABLE PROJECT (
    PROJECT_ID INT,
    EMPLOYEE_ID INT,
    PRIMARY KEY (PROJECT_ID, EMPLOYEE_ID),
    FOREIGN KEY (EMPLOYEE_ID) REFERENCES EMPLOYEE(EMPLOYEE_ID)
);

counterexample:
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (1, 'Alice', 2);
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (2, 'Bob', NULL);

INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (10, 1);
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (10, 2);

