INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Widget', 100);

-- In-window sales for product 1 (Q1 should include this product)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 10, 20, '2019-01-05', 2, 100);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 11, 21, '2019-03-30', 1, 120);

-- A sales row with NULL PRODUCT_ID and an out-of-window date (poisons Q2 via NULL in NOT IN subquery)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (NULL, 99, 77, '2018-12-31', 1, 1);

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'S8', 800);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'IPHONE', 900);

-- Buyer 10 buys an S8
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 101, 10, '2024-01-01', 1, 800);

-- iPhone sale with NULL buyer triggers NOT IN NULL-semantics issue in Q1
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 102, NULL, '2024-01-02', 1, 900);

